import React, { useState } from 'react';
import { Container, Row, Col, Card, Form, Button, Alert, ProgressBar, Nav, Tab } from 'react-bootstrap';
import axios from 'axios';

const ImportPortfolio = () => {
  const [file, setFile] = useState(null);
  const [fileType, setFileType] = useState('auto'); // 'auto', 'transactions', 'summary'
  const [uploading, setUploading] = useState(false);
  const [progress, setProgress] = useState(0);
  const [message, setMessage] = useState({ text: '', type: '' });
  const [previewData, setPreviewData] = useState(null);
  const [headers, setHeaders] = useState([]);
  const [mappedFields, setMappedFields] = useState({
    transactions: {
      date: 'Transaction Date',
      symbol: 'Stock Symbol',
      companyName: 'Company Name',
      isin: 'ISIN Code',
      action: 'Action',
      quantity: 'Quantity',
      price: 'Transaction Price',
      brokerage: 'Brokerage',
      exchange: 'Exchange'
    },
    summary: {
      symbol: 'Stock Symbol',
      companyName: 'Company Name',
      isin: 'ISIN Code',
      quantity: 'Qty',
      avgCostPrice: 'Average Cost Price',
      currentPrice: 'Current Market Price',
      valueAtCost: 'Value At Cost',
      valueAtMarket: 'Value At Market Price',
      realizedPL: 'Realized Profit / Loss',
      unrealizedPL: 'Unrealized Profit/Loss',
      unrealizedPLPercent: 'Unrealized Profit/Loss %'
    }
  });

  const detectFileType = (headers) => {
    // Check if headers match transaction file format
    const transactionKeywords = ['Transaction Date', 'Action', 'Brokerage', 'STT'];
    const summaryKeywords = ['Average Cost Price', 'Current Market Price', 'Unrealized Profit'];

    let transactionMatches = 0;
    let summaryMatches = 0;

    headers.forEach(header => {
      transactionKeywords.forEach(keyword => {
        if (header.includes(keyword)) transactionMatches++;
      });

      summaryKeywords.forEach(keyword => {
        if (header.includes(keyword)) summaryMatches++;
      });
    });

    if (transactionMatches > summaryMatches) return 'transactions';
    if (summaryMatches > transactionMatches) return 'summary';
    return 'unknown';
  };

  const handleFileChange = (e) => {
    const selectedFile = e.target.files[0];
    setFile(selectedFile);
    setMessage({ text: '', type: '' });

    if (selectedFile) {
      const reader = new FileReader();
      reader.onload = (event) => {
        try {
          // Parse CSV
          const text = event.target.result;
          const lines = text.split('\n');

          if (lines.length > 0) {
            const headerLine = lines[0];
            const detectedHeaders = headerLine.split(',').map(h => h.trim());
            setHeaders(detectedHeaders);

            // Auto-detect file type
            if (fileType === 'auto') {
              const detected = detectFileType(detectedHeaders);
              setFileType(detected !== 'unknown' ? detected : 'transactions');
            }

            // Display preview (up to 5 rows)
            const dataRows = lines.slice(1, 6).map(line => line.split(',').map(cell => cell.trim()));
            setPreviewData(dataRows);
          }
        } catch (error) {
          console.error("Error parsing file:", error);
          setMessage({ 
            text: 'Error parsing file. Please make sure it is a valid CSV file.',
            type: 'danger' 
          });
        }
      };
      reader.readAsText(selectedFile);
    }
  };

  const handleFieldMapping = (fileTypeKey, field, value) => {
    setMappedFields({
      ...mappedFields,
      [fileTypeKey]: {
        ...mappedFields[fileTypeKey],
        [field]: value
      }
    });
  };

  const handleFileTypeChange = (type) => {
    setFileType(type);
  };

  const handleUpload = async (e) => {
    e.preventDefault();

    if (!file) {
      setMessage({ text: 'Please select a file to upload', type: 'danger' });
      return;
    }

    const formData = new FormData();
    formData.append('file', file);
    formData.append('fileType', fileType);

    // Add field mappings for the selected file type
    const currentMapping = mappedFields[fileType];
    Object.keys(currentMapping).forEach(key => {
      formData.append(`field_${key}`, currentMapping[key]);
    });

    setUploading(true);
    setProgress(0);

    try {
      // This would normally point to your backend API
      // Since we don't have a real endpoint yet, we'll simulate success
      // await axios.post('/api/portfolio/import', formData, {
      //   onUploadProgress: (progressEvent) => {
      //     const percentCompleted = Math.round((progressEvent.loaded * 100) / progressEvent.total);
      //     setProgress(percentCompleted);
      //   }
      // });

      // Simulate upload progress
      for (let i = 0; i <= 100; i += 10) {
        await new Promise(resolve => setTimeout(resolve, 200));
        setProgress(i);
      }

      setMessage({ 
        text: `Portfolio ${fileType === 'transactions' ? 'transaction' : 'summary'} data imported successfully! You can now view your portfolio performance.`,
        type: 'success' 
      });

    } catch (error) {
      console.error(error);
      setMessage({ 
        text: 'Failed to import portfolio data. Please check your file format and try again.',
        type: 'danger' 
      });
    } finally {
      setUploading(false);
    }
  };

  const renderMappingFields = () => {
    const currentMapping = mappedFields[fileType];
    const fields = Object.keys(currentMapping);

    return fields.map(field => (
      <Form.Group className="mb-3" key={field}>
        <Form.Label>{field.charAt(0).toUpperCase() + field.slice(1).replace(/([A-Z])/g, ' $1')} Column</Form.Label>
        <Form.Control 
          type="text" 
          placeholder={`Enter ${field} column name`}
          value={currentMapping[field]}
          onChange={(e) => handleFieldMapping(fileType, field, e.target.value)}
          disabled={uploading}
        />
      </Form.Group>
    ));
  };

  const renderFileFormatGuidelines = () => {
    if (fileType === 'transactions') {
      return (
        <>
          <Card.Text>
            Your transaction file should contain the following information:
          </Card.Text>

          <ul>
            <li><strong>Stock Symbol:</strong> The ticker symbol of the security</li>
            <li><strong>Company Name:</strong> The full name of the company</li>
            <li><strong>ISIN Code:</strong> International Securities Identification Number</li>
            <li><strong>Action:</strong> Buy or Sell</li>
            <li><strong>Quantity:</strong> Number of shares</li>
            <li><strong>Transaction Price:</strong> Price per share</li>
            <li><strong>Transaction Date:</strong> Date of transaction (DD-MMM-YYYY format preferred)</li>
            <li><strong>Brokerage/Fees:</strong> Any transaction fees or commissions</li>
            <li><strong>Exchange:</strong> Stock exchange (e.g., NSE, BSE)</li>
          </ul>

          <Card.Text className="mt-3 mb-0">
            <strong>Example transaction CSV format:</strong>
          </Card.Text>
          <pre className="bg-light p-2 mt-2">
            Stock Symbol,Company Name,ISIN Code,Action,Quantity,Transaction Price,Brokerage,Transaction Charges,StampDuty,Segment,STT Paid/Not Paid,Remarks,Transaction Date,Exchange<br/>
            AARIND,AARTI INDUSTRIES LTD,INE769A01020,Buy,10,448.00,13.24,0.14,0.00,TT,STT Paid,icicidirect,21-Aug-2023,NSE<br/>
            AARIND,AARTI INDUSTRIES LTD,INE769A01020,Sell,5,460.00,6.82,0.07,0.00,TT,STT Paid,icicidirect,15-Sep-2023,NSE
          </pre>
        </>
      );
    } else if (fileType === 'summary') {
      return (
        <>
          <Card.Text>
            Your portfolio summary file should contain the following information:
          </Card.Text>

          <ul>
            <li><strong>Stock Symbol:</strong> The ticker symbol of the security</li>
            <li><strong>Company Name:</strong> The full name of the company</li>
            <li><strong>ISIN Code:</strong> International Securities Identification Number</li>
            <li><strong>Qty:</strong> Number of shares held</li>
            <li><strong>Average Cost Price:</strong> Average cost of acquisition per share</li>
            <li><strong>Current Market Price:</strong> Current market price per share</li>
            <li><strong>Value At Cost:</strong> Total cost of acquisition</li>
            <li><strong>Value At Market Price:</strong> Current market value of holding</li>
            <li><strong>Realized Profit/Loss:</strong> Profit/loss from sold positions</li>
            <li><strong>Unrealized Profit/Loss:</strong> Unrealized profit/loss on current positions</li>
          </ul>

          <Card.Text className="mt-3 mb-0">
            <strong>Example summary CSV format:</strong>
          </Card.Text>
          <pre className="bg-light p-2 mt-2">
            Stock Symbol,Company Name,ISIN Code,Qty,Average Cost Price,Current Market Price,% Change over prev close,Value At Cost,Value At Market Price,Realized Profit / Loss,Unrealized Profit/Loss,Unrealized Profit/Loss %<br/>
            AARIND,AARTI INDUSTRIES LTD,INE769A01020,2995,455.18,376.00,- 5.01,1363264.10,1126120.00,0.00,-237144.10,(17.40)<br/>
            ADAPOR,ADANI PORT AND SPECIAL ECONO,INE742F01042,0,0.00,1069.40,- 0.89,0.00,0.00,11123.10,0.00,0.00
          </pre>
        </>
      );
    }
  };

  return (
    <Container className="mt-4">
      <h1 className="mb-4">Import Portfolio Data</h1>

      {message.text && (
        <Alert variant={message.type}>
          {message.text}
          {message.type === 'success' && (
            <div className="mt-2">
              <Button variant="primary" href="/portfolios">View Portfolio</Button>
            </div>
          )}
        </Alert>
      )}

      <Row>
        <Col lg={6} className="mb-4">
          <Card>
            <Card.Body>
              <Card.Title>Upload Portfolio File</Card.Title>
              <Card.Text>
                Import your portfolio data from a CSV file.
              </Card.Text>

              <Form onSubmit={handleUpload}>
                <Form.Group className="mb-3">
                  <Form.Label>Choose File</Form.Label>
                  <div className="file-upload-container p-3 mb-3">
                    <Form.Control 
                      type="file" 
                      accept=".csv" 
                      onChange={handleFileChange}
                      disabled={uploading}
                    />
                  </div>

                  {file && (
                    <div className="mt-2 mb-3">
                      <p><strong>Selected file:</strong> {file.name}</p>
                    </div>
                  )}

                  {headers.length > 0 && (
                    <div className="mt-3 mb-3">
                      <Form.Group>
                        <Form.Label><strong>File Type:</strong></Form.Label>
                        <div>
                          <Form.Check
                            inline
                            type="radio"
                            id="auto-detect"
                            label="Auto-detect"
                            name="fileType"
                            checked={fileType === 'auto'}
                            onChange={() => handleFileTypeChange('auto')}
                            disabled={uploading}
                          />
                          <Form.Check
                            inline
                            type="radio"
                            id="transactions"
                            label="Transactions"
                            name="fileType"
                            checked={fileType === 'transactions'}
                            onChange={() => handleFileTypeChange('transactions')}
                            disabled={uploading}
                          />
                          <Form.Check
                            inline
                            type="radio"
                            id="summary"
                            label="Holdings Summary"
                            name="fileType"
                            checked={fileType === 'summary'}
                            onChange={() => handleFileTypeChange('summary')}
                            disabled={uploading}
                          />
                        </div>
                      </Form.Group>

                      {fileType !== 'auto' && (
                        <p className="text-muted mt-2">
                          Detected file type: <strong>{fileType}</strong>
                        </p>
                      )}
                    </div>
                  )}

                  {previewData && previewData.length > 0 && (
                    <div className="mt-3 mb-3">
                      <h6>File Preview:</h6>
                      <div className="table-responsive">
                        <table className="table table-sm table-bordered">
                          <thead>
                            <tr>
                              {headers.slice(0, 8).map((header, idx) => (
                                <th key={idx}>{header}</th>
                              ))}
                              {headers.length > 8 && <th>...</th>}
                            </tr>
                          </thead>
                          <tbody>
                            {previewData.map((row, rowIdx) => (
                              <tr key={rowIdx}>
                                {row.slice(0, 8).map((cell, cellIdx) => (
                                  <td key={cellIdx}>{cell}</td>
                                ))}
                                {row.length > 8 && <td>...</td>}
                              </tr>
                            ))}
                          </tbody>
                        </table>
                      </div>
                    </div>
                  )}

                  {uploading && (
                    <ProgressBar 
                      now={progress} 
                      label={`${progress}%`} 
                      className="mb-3"
                      animated
                    />
                  )}
                </Form.Group>

                <Button 
                  variant="primary" 
                  type="submit" 
                  disabled={!file || uploading || fileType === 'unknown'}
                >
                  {uploading ? 'Uploading...' : 'Upload Portfolio'}
                </Button>
              </Form>
            </Card.Body>
          </Card>
        </Col>

        <Col lg={6}>
          <Card>
            <Card.Body>
              <Card.Title>Column Mapping</Card.Title>
              <Card.Text>
                Map the columns in your file to the required fields.
              </Card.Text>

              {fileType !== 'auto' && fileType !== 'unknown' && renderMappingFields()}

              {fileType === 'auto' && (
                <p className="text-muted">
                  Please select a file to auto-detect or manually select the file type.
                </p>
              )}

              {fileType === 'unknown' && (
                <Alert variant="warning">
                  Could not automatically determine file type. Please select the file type manually.
                </Alert>
              )}
            </Card.Body>
          </Card>
        </Col>
      </Row>

      <Row className="mt-4">
        <Col>
          <Card>
            <Card.Body>
              <Card.Title>File Format Guidelines</Card.Title>

              <Tab.Container defaultActiveKey={fileType !== 'auto' ? fileType : 'transactions'}>
                <Nav variant="tabs" className="mb-3">
                  <Nav.Item>
                    <Nav.Link eventKey="transactions">Transactions File</Nav.Link>
                  </Nav.Item>
                  <Nav.Item>
                    <Nav.Link eventKey="summary">Summary File</Nav.Link>
                  </Nav.Item>
                </Nav>

                <Tab.Content>
                  <Tab.Pane eventKey="transactions">
                    {renderFileFormatGuidelines('transactions')}
                    <div className="mt-3">
                      <Button variant="outline-primary" href="/sample_transactions.csv" download>
                        Download Sample Transactions CSV
                      </Button>
                    </div>
                  </Tab.Pane>

                  <Tab.Pane eventKey="summary">
                    {renderFileFormatGuidelines('summary')}
                    <div className="mt-3">
                      <Button variant="outline-primary" href="/sample_summary.csv" download>
                        Download Sample Summary CSV
                      </Button>
                    </div>
                  </Tab.Pane>
                </Tab.Content>
              </Tab.Container>
            </Card.Body>
          </Card>
        </Col>
      </Row>
    </Container>
  );
};

export default ImportPortfolio;
